insert into public.eventos (entidade, entidade_id, acao, dados)
select * from (values
  ('cliente'::text, '11111111-1111-4111-8111-111111111111'::uuid, 'cliente_criado'::text, '{"origem":"seed_demo"}'::jsonb),
  ('form_envio', '22222222-2222-4222-8222-222222222222'::uuid, 'formulario_respondido', '{"origem":"seed_demo"}'::jsonb),
  ('diagnostico', '44444444-4444-4444-8444-444444444444'::uuid, 'diagnostico_revisado', '{"origem":"seed_demo","versao_motor":"1.0.0"}'::jsonb),
  ('proposta', '55555555-5555-4555-8555-555555555555'::uuid, 'proposta_enviada', '{"origem":"seed_demo","numero":"2026/0001"}'::jsonb)
) as semente(entidade, entidade_id, acao, dados)
where not exists (
  select 1 from public.eventos e
  where e.entidade = semente.entidade and e.entidade_id = semente.entidade_id and e.acao = semente.acao
);
